  const build = (await git(["rev-parse", "HEAD"])).trim();
  await git(["checkout", "-b", "task"]);
  await writeFile(source + "/identity.txt", "fixture-task\n");
  await git(["commit", "-qam", "fixture task"]);
  const task = (await git(["rev-parse", "HEAD"])).trim();
  await git(["checkout", "-b", "devcontainer", "main"]);
  await writeFile(source + "/identity.txt", "fixture-devcontainer\n");
  await git(["commit", "-qam", "fixture devcontainer"]);
  const customBuild = (await git(["rev-parse", "HEAD"])).trim();
  await git(["checkout", "main"]);
  await run(["git", "clone", "--bare", source, root + "/source.git"], { env });
  await run(["git", "-C", root + "/source.git", "config", "uploadpack.allowFilter", "true"], { env });
  const backends = new Set<ReturnType<typeof Bun.spawn>>();
  const server = Bun.serve({ hostname: "127.0.0.1", port: 0, async fetch(request) {
    const url = new URL(request.url);
    if (signal?.aborted) return new Response(null, { status: 503 });
    if (!url.pathname.startsWith("/source.git/") || url.pathname.includes("..")) return new Response(null, { status: 404 });
    const body = new Uint8Array(await request.arrayBuffer());
    const child = Bun.spawn(["git", "http-backend"], { env: { ...env, GIT_PROJECT_ROOT: root, GIT_HTTP_EXPORT_ALL: "1", PATH_INFO: url.pathname, QUERY_STRING: url.search.slice(1), REQUEST_METHOD: request.method, CONTENT_TYPE: request.headers.get("content-type") ?? "", HTTP_GIT_PROTOCOL: request.headers.get("git-protocol") ?? "", CONTENT_LENGTH: String(body.length) }, stdin: body, stdout: "pipe", stderr: "ignore" });
    backends.add(child);
    const timer = setTimeout(() => child.kill("SIGKILL"), 5_000);
    try {
      const output = Buffer.from(await new Response(child.stdout).arrayBuffer());
      if (await child.exited !== 0) return new Response(null, { status: 500 });
      const boundary = output.indexOf("\r\n\r\n");
      assert(boundary >= 0);
      const headers = new Headers();
      let status = 200;
      for (const line of output.subarray(0, boundary).toString().split("\r\n")) {
        const colon = line.indexOf(":");
        if (line.slice(0, colon).toLowerCase() === "status") status = Number(line.slice(colon + 1).trim().split(" ")[0]);
        else headers.append(line.slice(0, colon), line.slice(colon + 1).trim());
      }
      return new Response(output.subarray(boundary + 4), { status, headers });
    } finally { clearTimeout(timer); backends.delete(child); }
  }});
  const close = () => { server.stop(true); for (const child of backends) child.kill("SIGKILL"); };
  const url = `http://127.0.0.1:${server.port}/source.git`;
  try { await git(["remote", "add", "origin", url]); await git(["fetch", "origin"]); }
  catch (error) { close(); throw error; }
  return { source, build, task, customBuild, url, close };
}

