func resolveCommitSHA(ctx context.Context, repo *Repo, rev string) (string, error) {
	revResult, err := repo.run(ctx, "rev-parse", rev+"^{commit}")
	if err != nil {
		return "", fmt.Errorf("resolve immutable commit sha: %w", err)
	}
	commitSHA := strings.TrimSpace(string(revResult.Stdout))
	if commitSHA == "" {
		return "", fmt.Errorf("empty commit sha for revision %q", rev)
	}
	return commitSHA, nil
}

func cloneInspectionRepo(
	ctx context.Context,
	root string,
	info *GitInfo,
	env []string,
) (*Repo, error) {
	target := filepath.Join(root, "repo")
	args := []string{"clone", bloblessCloneFilter, "--no-checkout"}
	if info.Commit == "" {
		args = append(args, "--depth=1")
	}
	if info.Branch != "" {
		args = append(args, "--branch", info.Branch)
	}
	args = append(args, info.Repository, target)

	bootstrap := At("", WithEnv(env))
	if _, err := bootstrap.runner.Run(ctx, RunOptions{Env: bootstrap.env, Args: args}); err != nil {
		return nil, fmt.Errorf("inspect remote repository: %w", err)
	}
	return At(target, WithEnv(env)), nil
}

func selectInspectionRevision(ctx context.Context, repo *Repo, info *GitInfo) (string, error) {
	if info.PR != "" {
		return fetchInspectionPR(ctx, repo, info.Repository, info.PR)
	}
	if info.Commit != "" {
		return fetchInspectionCommit(ctx, repo, info.Commit)
	}
	return inspectionHeadRev, nil
}

func fetchInspectionPR(
	ctx context.Context,
	repo *Repo,
	repository, request string,
) (string, error) {
	number := prNumber(request)
	if number == "" {
		return "", fmt.Errorf("invalid pull/merge request reference %q", request)
	}
	candidates := prCandidates(repository)
	if len(candidates) == 0 {
		return "", fmt.Errorf("unsupported repository host for pull/merge request %q", repository)
	}
	var lastErr error
	for _, host := range candidates {
		refspec := host.Refspec(number)
		_, err := repo.run(ctx, "fetch", "--depth=1", "origin", refspec)
		if err == nil {
			return "FETCH_HEAD", nil
		}
		lastErr = err
	project := &projectSecretContext{config: cfg, sources: map[string]secrets.Source{}}
	for _, sourceConfig := range cfg.SecretSources {
		resolvedPath, err := secrets.ResolveProjectSourcePath(root, sourceConfig.Path)
		if err != nil {
			return nil, fmt.Errorf("load project secret source %q: %w", sourceConfig.Name, err)
		}
		project.sources[sourceConfig.Name] = secrets.NewSOPSSource(
			sourceConfig.Name,
			resolvedPath,
			sourceConfig.Format,
		)
	}
	return project, nil
}

func (cmd *UpCmd) discoverRemoteProjectSecrets(
	ctx context.Context,
	source *provider2.WorkspaceSource,
) (*projectSecretContext, error) {
	info := &gitpkg.GitInfo{
		Repository: source.GitRepository,
		Branch:     source.GitBranch,
		Commit:     source.GitCommit,
		PR:         source.GitPRReference,
		SubPath:    source.GitSubPath,
	}
	inspection, err := gitpkg.InspectRemote(ctx, info, cmd.gitInspectionEnv())
	if err != nil {
		return nil, err
	}
	defer func() { _ = inspection.Close() }()
	if inspection.Revision() != "" {
		source.GitCommit = inspection.Revision()
	}

	cfg, err := cmd.readRemoteProjectConfig(ctx, inspection)
	if err != nil || cfg == nil {
		return nil, err
	}

	sources, err := loadRemoteProjectSources(ctx, inspection, cfg)
	if err != nil {
		return nil, err
	}
	return &projectSecretContext{config: cfg, sources: sources}, nil
}

	if number == "" {
		return fmt.Errorf("not a pull/merge request reference: %q", prRef)
	}

	var lastErr error
	for _, host := range prCandidates(repoURL) {
		refspec := host.Refspec(number)
		prBranch := host.BranchName(number)
		log.Debugf("fetching %s request: %s", host.Name, refspec)

		err := r.Fetch(ctx, refspec+":"+prBranch)
		if err == nil {
			if err := r.Switch(ctx, prBranch); err != nil {
				return err
			}
			r.trackRequestSourceBranch(ctx, prBranch)
			return nil
		}
		if !isMissingRefError(err) {
			return err
		}
		lastErr = err
	}
	return lastErr
}

// isMissingRefError reports whether err is git failing to find the requested
// remote ref, as opposed to an auth, network, or cancellation failure.
func isMissingRefError(err error) bool {
	var cmdErr *CommandError
	if !errors.As(err, &cmdErr) {
		return false
	}
	msg := strings.ToLower(cmdErr.Stderr)
	return strings.Contains(msg, "couldn't find remote ref") ||
		strings.Contains(msg, "no such ref") ||
		strings.Contains(msg, "not found in upstream")
}

func (r *Repo) Reset(ctx context.Context, commit string, mode ResetMode) error {
	if err := r.runLogged(ctx, "reset", string(mode), commit); err != nil {
		return fmt.Errorf("reset head to %q: %w", commit, err)
	}
	return nil
}

// LsRemote reports whether the remote repository is reachable.
func (r *Repo) LsRemote(ctx context.Context, repository string) error {
	if _, err := r.run(ctx, "ls-remote", "--quiet", repository); err != nil {
		return fmt.Errorf("ls-remote %q: %w", repository, err)
	}
	return nil
}

// LsTree lists the files tracked at ref, recursively, as repo-relative paths.
func (r *Repo) LsTree(ctx context.Context, ref string) ([]string, error) {
	res, err := r.run(ctx, "ls-tree", "-r", "--full-name", "--name-only", ref)
	if err != nil {
		return nil, fmt.Errorf("ls-tree %q: %w", ref, err)
	}
	return splitLines(res.Stdout), nil
}

func (r *Repo) Clone(ctx context.Context, repository string, options ...Option) error {
	return r.cloneWith(ctx, repository, newCloneConfig(options...))
}

func (r *Repo) CloneFromInfo(
	ctx context.Context,
	gitInfo *GitInfo,
	helper string,
	options ...Option,
) error {
	options = append(
		[]Option{WithBranch(gitInfo.Branch), WithCredentialHelper(helper)},
		options...,
	)
	c := newCloneConfig(options...)

	if err := r.cloneWith(ctx, gitInfo.Repository, c); err != nil {
		return err
	}

	switch {
	case gitInfo.PR != "":
		if err := r.CheckoutPR(ctx, gitInfo.Repository, gitInfo.PR); err != nil {
			return err
		}
	case gitInfo.Commit != "":
		if err := r.Reset(ctx, gitInfo.Commit, ResetHard); err != nil {
			return err
		}
	}

	// Bare clones have no worktree to hydrate.
	if c.strategy != BareCloneStrategy {
		r.SetupLFS(ctx, c.lfsMode, c.allowLFSInstall)
	}
	return nil
}

// CredentialFill runs `git credential fill`, feeding request on stdin and
// returning git's response.
func (r *Repo) CredentialFill(ctx context.Context, request string) (string, error) {
	res, err := r.runner.Run(ctx, RunOptions{
		Dir:              r.path,
		Env:              r.env,
		Args:             []string{"credential", "fill"},
		Stdin:            strings.NewReader(request),
		UnredactedStdout: true,
	})
